# GTK 3 is the mature GTK application toolkit runtime. It remains required by
# many desktop applications even as newer applications move to GTK 4.
AddPackage gtk3

# Generated by gtk-query-immodules after GTK input-method modules change.
IgnorePath '/usr/lib/gtk-3.0/3.0.0/immodules.cache'

# GTK 4 is the current GTK application toolkit runtime.
AddPackage gtk4

# Generated by gtk-update-icon-cache for each installed icon theme.
IgnorePath '/usr/share/icons/*/icon-theme.cache'

# Tokyo Night supplies the shared GTK 2/3 theme used by legacy and mature GTK
# applications.
#
# GTK 4/libadwaita applications retain their supported dark-mode behavior
# through the desktop color-scheme preference, they don't support custom
# theming.
AddPackage --foreign tokyonight-gtk-theme-git
